import re
import sys

from playwright.sync_api import expect, sync_playwright


with sync_playwright() as playwright:
    browser = playwright.chromium.launch(headless=True)
    page = browser.new_page(viewport={"width": 1440, "height": 960}, locale="ko-KR")
    base_url = sys.argv[1]

    page.goto(base_url + "/#/jobs", wait_until="networkidle")
    expect(page.locator('#menu [data-menu="jobs"]')).to_have_attribute("aria-current", "page")
    expect(page.locator('#menu [data-menu="jobs"] .menu-label')).to_have_text("작업 관리")
    expect(page.locator('#menu [data-menu="status"]')).to_have_count(0)
    expect(page.locator("#menu .menu-count")).to_have_count(0)
    expect(page.locator('#active-jobs .work-row[data-work-id="JOB-RUNNING"]')).to_have_count(1)
    expect(page.locator('#queued-jobs .work-row[data-work-id="JOB-QUEUED"]')).to_have_count(1)
    attention = page.locator("#attention-jobs")
    expect(attention).to_have_attribute("open", "")
    expect(attention.locator("summary")).to_have_text("확인 필요1")
    expect(attention.locator('.work-row[data-work-id="JOB-REVIEW"]')).to_be_visible()
    attention.locator("summary").click()
    expect(attention).not_to_have_attribute("open", "")
    attention.locator("summary").click()
    expect(attention).to_have_attribute("open", "")
    completed_section = page.locator("#completed-jobs")
    expect(completed_section).not_to_have_attribute("open", "")
    expect(completed_section.locator(":scope > summary")).to_have_text("완료1")
    completed = completed_section.locator('.work-row[data-work-id="ARCHIVE-RUN-1"]')
    expect(completed).to_have_attribute("href", "#/runs/ARCHIVE-RUN-1")
    expect(completed).to_contain_text("8 폴더 · 795 영상")
    completed_section.locator(":scope > summary").click()
    expect(completed_section).to_have_attribute("open", "")
    completed.click()

    expect(page).to_have_url(base_url + "/#/runs/ARCHIVE-RUN-1")
    expect(page.locator("#run-summary")).to_have_attribute("title", re.compile("작업 ID ARCHIVE-RUN-1"))
    expect(page.locator("#run-summary")).to_contain_text("795")
    expect(page.locator("#run-scope .data-row")).to_have_count(8)
    result = page.locator('#run-results [data-package-id="VP-20261030-SOURCE"]')
    expect(result).to_contain_text("source.mp4")
    expect(result).to_contain_text("소스 시퀀스")
    expect(result).to_contain_text("86 → 1")
    expect(result).to_contain_text("archive-main")
    expect(result.locator(".archive-relative-path")).to_have_text("packages/2026/10/30/VP-20261030-SOURCE/revisions/000001")
    child = page.locator('#run-children .job-row[data-job-id="JOB-SOURCE"] a')
    expect(child).to_have_attribute("href", "#/jobs/JOB-SOURCE")
    child.click()
    expect(page).to_have_url(base_url + "/#/jobs/JOB-SOURCE")
    expect(page.locator("#job-title")).to_have_text("source.mp4")
    archive_result = page.locator("#job-result .archive-result-link")
    expect(archive_result).to_have_attribute("href", "#/runs/ARCHIVE-RUN-1?result=VP-20261030-SOURCE")
    archive_result.click()
    expect(page).to_have_url(base_url + "/#/runs/ARCHIVE-RUN-1?result=VP-20261030-SOURCE")
    expect(page.locator('#run-results [data-package-id="VP-20261030-SOURCE"]')).to_have_attribute("data-selected", "true")

    page.goto(base_url + "/#/drives/VOLUME-1", wait_until="networkidle")
    entry = page.locator('#completed-work a.completed-row[data-package-id="VP-20261030-SOURCE"]')
    expect(entry).to_have_attribute("href", "#/runs/ARCHIVE-RUN-1?result=VP-20261030-SOURCE")
    entry.click()
    expect(page).to_have_url(base_url + "/#/runs/ARCHIVE-RUN-1?result=VP-20261030-SOURCE")
    expect(page.locator('#run-results [data-package-id="VP-20261030-SOURCE"]')).to_have_attribute("data-selected", "true")
    browser.close()
